#!/bin/bash
# full regression on one bundle, three streams: bash reg-all.sh <bundle> <tag>
B=$1; T=$2; W=${W:-$(cd "$(dirname "$0")" && pwd)}; O=$W/reg-$T; mkdir -p $O; rm -f $O/*.out
one() { # kind dir file
  local out; out=$( cd $W/$2 && WORKER=$B OLD=$W/clean/m41-clean.mjs timeout 580 node --no-warnings --import $W/m23/sameday-shim.mjs $( [ "$1" = run ] && echo "--import $W/m39/lab-old-shim.mjs" ) $3 2>&1 | grep -E "^FAIL|ALL OK|FAILED|ERR|Error" | cut -c1-260 | tr '\n' ' ' ); echo "== $3: ${out:-NO OUTPUT}" ; }
L=( "run m17 t-m17.mjs" "run m18 t-m18.mjs" "run m18 t-m18ui.mjs" "run m19 t-m19.mjs" "run m20 t-m20.mjs" "run m21 t-m21.mjs" "run m22 t-m22.mjs" "run m22 t-m22ui.mjs" "run m23 t-m23.mjs" "run m23 t-m23ui.mjs" "run m25 t-m25.mjs" "run m25 t-m25ui.mjs" "run m26 t-m26.mjs" "run m26 t-m26ui.mjs" "run m27 t-m27.mjs" "run m27 t-m27ui.mjs" "run m28 t-m28ui.mjs" "run m29 t-m29.mjs" "run m29 t-m29ui.mjs" "run m30 t-m30.mjs" "run m30 t-m30ui.mjs" "run m31 t-m31.mjs" "run m31 t-m31ui.mjs" "run audit e2e10-m36.mjs" "run m32 t-m32ui.mjs" "run m33 t-m33.mjs" "run m33 t-m33ui.mjs" "run m34 t-m34ui.mjs" "run m35 t-m35.mjs" "run m35 t-m35ui.mjs" "run m35 t-m35rx.mjs" "run m35 t-m35fin.mjs" "runn m37 t-m36.mjs" "runn m37 t-m36mig.mjs" "runn m37 t-m36ui.mjs" "runn m37 t-m37.mjs" "runn m38 t-m38.mjs" "runn m38 t-m38ui.mjs" "runn m39 t-m39ui.mjs" "runn m40 t-m40.mjs" "runn m40 t-m40ui.mjs" "runn m41 t-m41ui.mjs" "runn m41b t-m41b.mjs" "runn m41b t-m41bui.mjs" "runn m42 t-m42.mjs" "runn m42 t-m42ui.mjs" "runn m42b t-m42bui.mjs" "runn m42c t-m42cui.mjs" "runn m42d t-m42d.mjs" "runn m42d t-m42dui.mjs" "runn m42e t-m42e.mjs" "runn m43a t-m43aui.mjs" "runn m43b t-m43b.mjs" "runn m43b t-m43bui.mjs" "runn m43c t-m43c.mjs" "runn m43e t-m43eui.mjs" "runn m43f t-m43fui.mjs" "runn m44b t-m44bui.mjs" "runn m43g t-m43gui.mjs" "runn m45a t-m45a.mjs" "runn m45a t-m45aui.mjs" "runn m45b t-m45b.mjs" "runn m46a t-m46aui.mjs" "runn m46b t-m46bui.mjs" "runn m46c t-m46c.mjs" "runn m46c t-m46cui.mjs" "runn m47a t-m47a.mjs" "runn m58a t-m58a.mjs" "runn m58b t-m58b.mjs" "runn m59a t-m59a.mjs" "runn m60a t-m60a.mjs" "runn m61a t-m61a.mjs" "runn m48a t-m48aui.mjs" "runn m49a t-m49a.mjs" "runn m50a t-m50a.mjs" "runn m50b t-m50b.mjs" "runn m50c t-m50cui.mjs" "runn m50d t-m50dui.mjs" "runn m50e t-m50eui.mjs" "runn m51a t-m51a.mjs" "runn m52a t-m52a.mjs" "runn m53a t-m53a.mjs" "runn m54c t-m54c.mjs" "runn m55a t-m55a.mjs" "runn m57a t-m57a.mjs" "runn m54b t-m54b.mjs" "runn m43d t-m43d.mjs" "runn m43d t-m43dui.mjs" "runn m44a t-m44a.mjs" "runn m44a t-m44aui.mjs" )
for s in 0 1 2 3; do ( i=0; for e in "${L[@]}"; do if [ $((i % 4)) -eq $s ]; then one $e >> $O/s$s.out; fi; i=$((i+1)); done; echo DONE >> $O/s$s.out ) & done; wait; cat $O/s*.out > $W/reg-$T.out; echo ALLDONE >> $W/reg-$T.out
